import backtrader as bt


class MomentumIchimokuSMA(bt.Strategy):
    def __init__(self):
        self.sma9 = bt.indicators.SimpleMovingAverage(self.data.close, period=9)
        self.sma26 = bt.indicators.SimpleMovingAverage(self.data.close, period=26)
        self.sma52 = bt.indicators.SimpleMovingAverage(self.data.close, period=52)
        self.crossover = bt.indicators.CrossOver(self.sma9, self.sma26)
        self.order = None

    def notify_order(self, order):
        if order.status in (
            order.Completed,
            order.Canceled,
            order.Margin,
            order.Rejected,
        ):
            self.order = None

    def next(self):
        if self.order:
            return

        close = self.data.close[0]
        sma26 = self.sma26[0]
        sma52 = self.sma52[0]

        if self.position.size > 0:
            if self.crossover[0] < 0 or close < min(sma26, sma52):
                self.order = self.close()
        elif self.position.size < 0:
            if self.crossover[0] > 0 or close > max(sma26, sma52):
                self.order = self.close()
        elif (
            self.crossover[0] > 0
            and close > sma26
            and close > sma52
            and sma26 > sma52
        ):
            self.order = self.order_target_percent(target=1.0)
        elif (
            self.crossover[0] < 0
            and close < sma26
            and close < sma52
            and sma26 < sma52
        ):
            self.order = self.order_target_percent(target=-1.0)
